                    ).match()
                }
            )
        }
    }

    test("test-entrezdirect-esummary-assembly-stub") {
        options '-stub'

        when {
            process {
                """
                input[0] = [
				    [ id:'test_assembly' ], // meta map
				    uid = '191021',
				    []
				]
				input[1] = 'assembly'

                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }

}

